async def act(page):
    # Click on the 'Epoch & Drift Benchmark' link to navigate to the homepage
    await page.get_by_role("link", name="Epoch & Drift Benchmark").click()
    await page.wait_for_load_state("networkidle")
    # Now search for the 'Archives' widget on the new page
    archives_element = page.get_by_text('Archives', exact=False)
    if await archives_element.count() > 0:
        june_link = archives_element.get_by_role('link', name='June 2024', exact=False)
        if await june_link.count() > 0:
            await june_link.click()
            await page.wait_for_load_state('networkidle')
            return
        else:
            june_link_global = page.get_by_role('link', name='June 2024', exact=False)
            if await june_link_global.count() > 0:
                await june_link_global.click()
                await page.wait_for_load_state('networkidle')
                return
            else:
                print("Link for 'June 2024' not found near Archives element.")
    else:
        archives_widget = page.get_by_role('complementary', name='Archives', exact=False)
        if await archives_widget.count() == 0:
            archives_widget = page.get_by_role('region', name='Archives', exact=False)
        if await archives_widget.count() == 0:
            archives_widget = page.get_by_role('widget', name='Archives', exact=False)
        if await archives_widget.count() == 0:
            archives_widget = page.get_by_role('navigation', name='Archives', exact=False)
        if await archives_widget.count() == 0:
            archives_widget = page.get_by_role('group', name='Archives', exact=False)
        if await archives_widget.count() > 0:
            june_link = archives_widget.get_by_role('link', name='June 2024', exact=False)
            if await june_link.count() > 0:
                await june_link.click()
                await page.wait_for_load_state('networkidle')
                return
            else:
                print("Link for 'June 2024' not found in Archives widget.")
        else:
            frames = page.frames
            for frame in frames:
                archives_in_frame = frame.get_by_text('Archives', exact=False)
                if await archives_in_frame.count() > 0:
                    june_link_in_frame = archives_in_frame.get_by_role('link', name='June 2024', exact=False)
                    if await june_link_in_frame.count() > 0:
                        await june_link_in_frame.click()
                        await page.wait_for_load_state('networkidle')
                        return
                    else:
                        print(f"Link for 'June 2024' not found in frame: {frame.name}")
            june_link_anywhere = page.get_by_text('June 2024', exact=False)
            if await june_link_anywhere.count() > 0:
                await june_link_anywhere.click()
                await page.wait_for_load_state('networkidle')
                return
            else:
                print("Archives widget and 'June 2024' link not found on the homepage.")

